/** Normaliza texto, mídia, sessão e qualquer arquivo binário para o roteamento multimodal. */
const body = $json.body ?? $json;
const text = $json.chatInput ?? body.text ?? body.message ?? '';
const mime = body.mime_type ?? body.mimeType ?? $json.mime_type ?? ($binary?.data?.mimeType ?? '');
const hasBinary = !!$binary?.data;
const caption = String(text || '').trim();
const mimeType = String(mime || '').toLowerCase();
const hasText = caption.length > 0;
const isImage = mimeType.startsWith('image/') || (hasBinary && String($binary?.data?.mimeType ?? '').toLowerCase().startsWith('image/'));
const isAudio = mimeType.startsWith('audio/') || (hasBinary && String($binary?.data?.mimeType ?? '').toLowerCase().startsWith('audio/'));
const isDocument = hasBinary && !isImage && !isAudio;
let inputType = 'unknown';
if (isImage && hasText) inputType = 'image_with_caption';
else if (isImage) inputType = 'image';
else if (isAudio) inputType = 'audio';
else if (isDocument && hasText) inputType = 'document_with_caption';
else if (isDocument) inputType = 'document';
else if (hasText) inputType = 'text';
const sessionId = String($json.sessionId ?? $json.session_id ?? body.sessionId ?? body.session_id ?? $json.chatId ?? body.chatId ?? $execution.id);
const conversationId = String($json.conversationId ?? $json.conversation_id ?? body.conversationId ?? body.conversation_id ?? sessionId);
const userId = String($json.userId ?? $json.user_id ?? body.userId ?? body.user_id ?? 'anonymous');
const output = { json: { ...body, text: caption, caption, mime_type: mimeType, input_type: inputType, has_caption: (isImage || isDocument) && hasText, session_id: sessionId, conversation_id: conversationId, user_id: userId }, pairedItem: { item: 0 } };
if (hasBinary) output.binary = $binary;
return output;

/** Consolida o resultado de cada rota e preserva a legenda. */
const input = $json;
const extracted = input.content_text || input.text || input.data || input.output || input.response || input.transcription || 'Não foi encontrado conteúdo textual para analisar.';
const caption = String(input.caption || '').trim();
const isDocumentWithCaption = input.processing_mode === 'document_with_caption' || input.processing_mode === 'user_document_with_caption' || input.input_type === 'document_with_caption';
const content = caption && isDocumentWithCaption
  ? `Legenda do usuário: ${caption}\n\nConteúdo do documento:\n${extracted}`
  : String(extracted);
return { json: { ...input, content_text: content, content_type: input.content_type || input.input_type || 'unknown' }, binary: $binary };

const original = $('Entrada - Normalizar').first().json;
const answer = $json.output ?? $json.text ?? $json.response ?? '';
return { json: { session_id: original.session_id, user_id: original.user_id, conversation_id: original.conversation_id, message_id: original.message_id || original.waha_message_id || '', user_message: original.text || original.caption || original.chatInput || '', assistant_message: String(answer), source: original.source || 'chat', received_at: original.received_at || null, processed_at: new Date().toISOString() } };

const items = $input.all();
const norm = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const containsAny = (text, terms) => terms.some((term) => text.includes(term));
const stopWords = new Set(['fatec','bebedouro','cps','qual','quais','onde','como','quando','porque','por','uma','das','dos','que','com','para','pela','pelo','tem','pode','posso','nao','sobre','esta','esse','essa','isso','aqui','meu','minha','seu','sua','voce','encontro','encontrar','site','oficial','e','o','a','os','as','de','do','da','no','na','nos','nas','um','ao','em','ser','sao','faz','fazer','mais','menos','me','eu','todas','outras','outra','unidades','rede','estado','cidades','lista','demais','qualquer','toda']);
const allFatecsTerms = ['todas as fatecs','todas fatecs','todas as fatec','outras fatecs','outra fatec','demais fatecs','qualquer fatec','todas as unidades','outras unidades','toda a rede','rede de fatecs','fatecs do estado','fatecs de sao paulo','lista de fatecs','lista das fatecs','outras cidades'];
const courseListTerms = ['quais cursos','quais sao os cursos','quais os cursos','cursos oferecidos','qual curso'];
return items.map((item) => {
  const parts = [item.json.text,item.json.caption,item.json.content_text].map((value) => String(value || '').trim()).filter(Boolean);
  const searchQuestion = [...new Set(parts)].join(' ');
  const normalized = norm(searchQuestion);
  const isVestibular = containsAny(normalized,['vestibular','inscricao','inscrever','processo seletivo','edital','candidato','prova','calendario','classificacao','convocacao','chamada','isencao','taxa de inscricao']);
  const isFatec = containsAny(normalized,['fatec','bebedouro','cps','tcc','monografia','estagio','area do aluno','aluno','biblioteca','livro','renovar','grade','matriz curricular','disciplina','documento','siga','academico','curso','logistica','agronegocio','big data','matricula','secretaria','historico','requerimento']);
  const wantsAllFatecs = containsAny(normalized,allFatecsTerms);
  const courseListFAQ = isFatec && !isVestibular && !wantsAllFatecs && containsAny(normalized,courseListTerms);
  const searchRoute = isVestibular ? 'vestibular' : courseListFAQ ? 'general' : isFatec ? 'bebedouro' : 'general';
  const terms = [...new Set(norm(searchQuestion).match(/[a-z0-9]{3,}/g) || [])].filter((term) => !stopWords.has(term)).slice(0,12);
  return { json: { ...item.json, searchRoute, searchQuestion, searchQuery: terms.join(' '), wantsAllFatecs, courseListFAQ }, ...(item.binary ? { binary: item.binary } : {}) };
});

const response = $input.first().json;
const body = response.body ?? response;
const original = $('Classificar - Fonte').first().json;
const norm = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const allowedHost = original.searchRoute === 'vestibular' ? 'vestibular.fatec.sp.gov.br' : 'fatecbb.cps.sp.gov.br';
const parseUrl = (value) => {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw.startsWith('https://') && !raw.startsWith('http://')) return null;
  const rest = raw.slice(raw.indexOf('://') + 3);
  const slash = rest.indexOf('/');
  return { host: slash < 0 ? rest.split(/[?#]/)[0] : rest.slice(0,slash) };
};
const question = norm(original.searchQuestion || original.searchQuery);
const topics = ['big data','agronegocio','monografia','tcc','estagio','biblioteca','renovar','disciplina','matriz curricular','grade curricular','documento','siga','vestibular','inscricao','processo seletivo','edital','prova','calendario'];
const requiredTopics = topics.filter((term) => question.includes(term));
const stop = new Set(['fatec','bebedouro','cps','sobre','para','como','onde','qual','quais','quando','porque','uma','das','dos','que','com','tem','pode','posso','site','oficial','fazer','esta','esse','essa','isso','aqui','meu','minha','seu','sua','no','na','do','da','pela','pelo']);
const queryTokens = [...new Set(norm(original.searchQuery).match(/[a-z0-9]{4,}/g) || [])].filter((token) => !stop.has(token));
const candidates = Array.isArray(body.results) ? body.results : [];
const results = candidates.filter((result) => {
  const parsed = parseUrl(result.url);
  if (!parsed || parsed.host !== allowedHost) return false;
  const content = String(result.content || '').trim();
  if (content.length < 20 || /pagina oficial de referencia|busca nao retornou trecho|placeholder/i.test(norm(content))) return false;
  const text = norm(String(result.title || '') + ' ' + content);
  if (requiredTopics.some((term) => !text.includes(term))) return false;
  const nonTopicTokens = queryTokens.filter((token) => !requiredTopics.some((term) => term.includes(token)));
  const matches = nonTopicTokens.filter((token) => text.includes(token)).length;
  return nonTopicTokens.length === 0 || matches >= Math.min(1, nonTopicTokens.length);
});
return [{ json: { ...original, sourceLabel: allowedHost, results, foundEvidence: results.length > 0 } }];

const response = $input.first().json;
const body = response.body ?? response;
const original = $('Classificar - Fonte').first().json;
const wantsAll = !!original.wantsAllFatecs;
const norm = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const question = norm(original.searchQuestion || original.searchQuery);
const topics = ['big data','agronegocio','monografia','tcc','estagio','biblioteca','renovar','disciplina','matriz curricular','grade curricular','documento','siga','vestibular','inscricao','processo seletivo','edital','prova','calendario'];
const requiredTopics = topics.filter((term) => question.includes(term));
const stop = new Set(['fatec','bebedouro','cps','sobre','para','como','onde','qual','quais','quando','porque','uma','das','dos','que','com','tem','pode','posso','site','oficial','fazer','esta','esse','essa','isso','aqui','meu','minha','seu','sua','no','na','do','da','pela','pelo']);
const queryTokens = [...new Set(norm(original.searchQuery).match(/[a-z0-9]{4,}/g) || [])].filter((token) => !stop.has(token));
const parseUrl = (value) => {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw.startsWith('https://') && !raw.startsWith('http://')) return null;
  const rest = raw.slice(raw.indexOf('://') + 3);
  const slash = rest.indexOf('/');
  return { host: slash < 0 ? rest.split(/[?#]/)[0] : rest.slice(0,slash), path: slash < 0 ? '/' : rest.slice(slash).split(/[?#]/)[0] };
};
const bebedouroPaths = ['/fatecs/fatec-bebedouro-jorge-caram-sabbag','/cursos-fatec/big-data-no-agronegocio','/cursos-fatec/logistica'];
const pathAllowed = (path) => wantsAll ? path === '/fatecs' || path.startsWith('/fatecs/') : bebedouroPaths.some((prefix) => path === prefix || path.startsWith(prefix + '/'));
const candidates = Array.isArray(body.results) ? body.results : [];
const results = candidates.filter((result) => {
  const parsed = parseUrl(result.url);
  if (!parsed || parsed.host !== 'www.cps.sp.gov.br' || !pathAllowed(parsed.path)) return false;
  const content = String(result.content || '').trim();
  if (content.length < 20 || /pagina oficial de referencia|busca nao retornou trecho|placeholder/i.test(norm(content))) return false;
  const text = norm(String(result.title || '') + ' ' + content);
  if (requiredTopics.some((term) => !text.includes(term))) return false;
  const nonTopicTokens = queryTokens.filter((token) => !requiredTopics.some((term) => term.includes(token)));
  const matches = nonTopicTokens.filter((token) => text.includes(token)).length;
  return nonTopicTokens.length === 0 || matches >= Math.min(1, nonTopicTokens.length);
});
return [{ json: { ...original, sourceLabel: wantsAll ? 'www.cps.sp.gov.br/fatecs (todas as unidades)' : 'www.cps.sp.gov.br (paginas da Fatec Bebedouro)', results, foundEvidence: results.length > 0 } }];

const item = $input.first().json;
const wantsAll = !!item.wantsAllFatecs;
const norm = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const parseUrl = (value) => {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw.startsWith('https://') && !raw.startsWith('http://')) return null;
  const rest = raw.slice(raw.indexOf('://') + 3);
  const slash = rest.indexOf('/');
  return { host: slash < 0 ? rest.split(/[?#]/)[0] : rest.slice(0,slash), path: slash < 0 ? '/' : rest.slice(slash).split(/[?#]/)[0] };
};
const cpsPaths = ['/fatecs/fatec-bebedouro-jorge-caram-sabbag','/cursos-fatec/big-data-no-agronegocio','/cursos-fatec/logistica'];
const cpsPathAllowed = (path) => wantsAll ? path === '/fatecs' || path.startsWith('/fatecs/') : cpsPaths.some((prefix) => path === prefix || path.startsWith(prefix + '/'));
const candidates = Array.isArray(item.results) ? item.results : [];
const results = item.foundEvidence === true ? candidates.filter((result) => {
  const parsed = parseUrl(result.url);
  if (!parsed) return false;
  const hostAllowed = parsed.host === 'fatecbb.cps.sp.gov.br' || parsed.host === 'vestibular.fatec.sp.gov.br' || (parsed.host === 'www.cps.sp.gov.br' && cpsPathAllowed(parsed.path));
  const content = String(result.content || '').trim();
  return hostAllowed && content.length >= 20 && !/pagina oficial de referencia|busca nao retornou trecho|placeholder/i.test(norm(content));
}).slice(0,4) : [];
const hasValidatedEvidence = results.length > 0;
let output;
if (!hasValidatedEvidence) {
  output = 'Não encontrei conteúdo textual oficial suficientemente relevante nas fontes permitidas para responder com segurança. Não vou inferir essa informação. Tente novamente mais tarde ou consulte a unidade.';
} else {
  output = 'Encontrei estes trechos nas fontes oficiais permitidas. Para evitar informações não confirmadas, reproduzo os trechos e links da busca:\n\n' + results.map((result,index) => {
    const clean = (value) => String(value || '').replaceAll(String.fromCharCode(10),' ').replaceAll(String.fromCharCode(13),' ').trim();
    return `${index+1}. **${clean(result.title || 'Fonte oficial')}**\n   Trecho: ${clean(result.content).slice(0,900)}\n   Fonte: [${result.url}](${result.url})`;
  }).join('\n\n');
}
return [{ json: { ...item, results: hasValidatedEvidence ? results : [], foundEvidence: hasValidatedEvidence, responseType: hasValidatedEvidence ? 'validated_search_excerpt' : 'insufficient_evidence', answerBasis: hasValidatedEvidence ? 'validated_official_excerpt' : 'insufficient_official_evidence', output } }];

