    { id: 'vestibular', label: 'Vestibular Fatec - Centro Paula Souza (processo seletivo)', domain: 'vestibular.fatec.sp.gov.br', escopo: 'vestibular', prioridade: 2 },
    { id: 'cps_bebedouro', label: 'Pagina institucional da Fatec Bebedouro no portal do CPS', domain: 'www.cps.sp.gov.br', caminho: '/fatecs/fatec-bebedouro-jorge-caram-sabbag', escopo: 'bebedouro', prioridade: 3 },
    { id: 'cps_curso_bigdata', label: 'Pagina oficial do curso Big Data no Agronegocio (CPS)', domain: 'www.cps.sp.gov.br', caminho: '/cursos-fatec/big-data-no-agronegocio', escopo: 'bebedouro', prioridade: 3 },
    { id: 'cps_curso_logistica', label: 'Pagina oficial do curso Logistica (CPS)', domain: 'www.cps.sp.gov.br', caminho: '/cursos-fatec/logistica', escopo: 'bebedouro', prioridade: 3 },
    { id: 'cps_todas_fatecs', label: 'Diretorio de todas as Fatecs no portal do CPS - somente quando pedido explicitamente', domain: 'www.cps.sp.gov.br', caminho: '/fatecs', escopo: 'todas_fatecs', prioridade: 4 }
  ],
